def item_label(slug: str) -> str:
    """Russian name for a magic item, or the slug when none is known."""
    return ITEM_LABELS.get(slug) or _ITEMS_FOLDED.get(slug.casefold()) or slug






def label(term: str, *, fallback: str | None = None) -> str:
    """Russian wording for an English rules term.

    Unknown terms come back unchanged unless ``fallback`` is supplied; the
    engine never invents a translation, so a missing label stays visible.
    """
    russian = LABELS.get(term)
    if russian is None:
        # Rules text varies in case ("Advantage" in a heading, "advantage"
        # mid-sentence), so the table is matched case-insensitively.
        russian = _LABELS_FOLDED.get(term.casefold())
    if russian is None:
        # Conditions and items live in their own tables; a caller
        # reaching for label("prone") should not get English back.
        folded = term.casefold()
        russian = (
            _CONDITIONS_FOLDED.get(folded)
            or _ITEMS_FOLDED.get(folded)
            or _ENTITIES_FOLDED.get(folded)
            or _REASONS_FOLDED.get(folded)
            or _TERMS_FOLDED.get(folded)
        )
    if russian is not None:
        return russian
    return term if fallback is None else fallback



